#!/usr/bin/env python3
"""Produce a read-only stock reconciliation receipt for one JSON case."""

import json
import sys


EVENT_FIELDS = {"id", "type", "sku", "quantity"}
EVENT_TYPES = {"receipt", "ship", "reserve"}


def _integer(value):
    return isinstance(value, int) and not isinstance(value, bool) and value >= 0


def _receipt(case_id, status, issue, on_hand=None, available=None):
    return {
        "case_id": case_id,
        "status": status,
        "on_hand": on_hand or {},
        "available": available or {},
        "issue": issue,
        "action_performed": False,
    }


def reconcile(case):
    """Return the desk receipt for a decoded case without mutating the case."""
    if not isinstance(case, dict):
        return _receipt(None, "needs_review", "invalid")

    case_id = case.get("case_id")
    if "opening" not in case or "events" not in case:
        return _receipt(case_id, "needs_input", "missing")

    opening = case["opening"]
    events = case["events"]
    if (
        not isinstance(case_id, str)
        or not case_id
        or not isinstance(opening, dict)
        or not isinstance(events, list)
        or any(not isinstance(sku, str) or not sku or not _integer(qty)
               for sku, qty in opening.items())
    ):
        return _receipt(case_id, "needs_review", "invalid")

    for event in events:
        if (
            not isinstance(event, dict)
            or set(event) != EVENT_FIELDS
            or not isinstance(event["id"], str)
            or not event["id"]
            or not isinstance(event["type"], str)
            or event["type"] not in EVENT_TYPES
            or not isinstance(event["sku"], str)
            or not event["sku"]
            or event["sku"] not in opening
            or not _integer(event["quantity"])
        ):
            return _receipt(case_id, "needs_review", "invalid")

    unique = []
    by_id = {}
    for event in events:
        event_id = event["id"]
        if event_id in by_id:
            if event != by_id[event_id]:
                return _receipt(case_id, "needs_review", "conflict")
        else:
            by_id[event_id] = event
            unique.append(event)

    on_hand = dict(opening)
    available = dict(opening)
    for event in unique:
        sku = event["sku"]
        quantity = event["quantity"]
        if event["type"] == "receipt":
            on_hand[sku] += quantity
            available[sku] += quantity
        elif event["type"] == "ship":
            on_hand[sku] -= quantity
            available[sku] -= quantity
        else:
            available[sku] -= quantity

    if any(value < 0 for value in on_hand.values()) or any(
        value < 0 for value in available.values()
    ):
        return _receipt(case_id, "needs_review", "negative")
    return _receipt(case_id, "completed", "none", on_hand, available)


def main(argv):
    if len(argv) != 3:
        print(f"usage: {argv[0]} INPUT.json OUTPUT.json", file=sys.stderr)
        return 2
    try:
        with open(argv[1], "r", encoding="utf-8") as source:
            case = json.load(source)
        result = reconcile(case)
        with open(argv[2], "w", encoding="utf-8") as destination:
            json.dump(result, destination, separators=(",", ":"), ensure_ascii=False)
            destination.write("\n")
    except (OSError, json.JSONDecodeError) as error:
        print(f"reconciliation failed: {error}", file=sys.stderr)
        return 2
    return 0


if __name__ == "__main__":
    raise SystemExit(main(sys.argv))
